import{_ as r,o as a,c as d,a2 as o}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"权限模型","description":"","frontmatter":{},"headers":[],"relativePath":"admin/permissions.md","filePath":"admin/permissions.md","lastUpdated":1785772843000}'),e={name:"admin/permissions.md"};function l(i,t,n,s,h,u){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="权限模型" tabindex="-1">权限模型 <a class="header-anchor" href="#权限模型" aria-label="Permalink to &quot;权限模型&quot;">​</a></h1><p>ZViewer 的权限系统分为四个角色，从高到低分别是 <strong>root（超级管理员）</strong>、<strong>admin（管理员）</strong>、<strong>user（普通用户）</strong> 和 <strong>guest（游客）</strong>。下面这张表能让你一目了然地知道每个角色能做什么、不能做什么。</p><h2 id="四层角色对比" tabindex="-1">四层角色对比 <a class="header-anchor" href="#四层角色对比" aria-label="Permalink to &quot;四层角色对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>root</th><th>admin</th><th>user</th><th>guest</th></tr></thead><tbody><tr><td>进入管理后台</td><td>✅</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>审核用户注册</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td>修改他人角色</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td>删除任意用户</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td>删除任意房间</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td>创建房间</td><td>✅</td><td>✅</td><td>视设置而定</td><td>❌</td></tr><tr><td>完全控制自己的房间</td><td>✅</td><td>✅</td><td>✅</td><td>❌</td></tr><tr><td>加入房间观看</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>发送评论与弹幕</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>修改系统设置</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td>检查并应用更新</td><td>✅</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td>管理服务器文件</td><td>✅</td><td>❌</td><td>❌</td><td>❌</td></tr></tbody></table><blockquote><p><strong>简单记法</strong>：root 拥有所有权限；admin 可以管理房间和更新，但不能管理用户；user 可以观看和互动，可能可以创建房间；guest 只能观看和互动，不能创建房间。</p></blockquote><hr><h2 id="注册与审核流程" tabindex="-1">注册与审核流程 <a class="header-anchor" href="#注册与审核流程" aria-label="Permalink to &quot;注册与审核流程&quot;">​</a></h2><h3 id="三种注册模式" tabindex="-1">三种注册模式 <a class="header-anchor" href="#三种注册模式" aria-label="Permalink to &quot;三种注册模式&quot;">​</a></h3><p>管理员可以在后台「基础设置」中选择注册模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>效果</th></tr></thead><tbody><tr><td><strong>开放注册（open）</strong></td><td>任何人注册后自动激活，直接成为 user 角色</td></tr><tr><td><strong>审批注册（approval）</strong></td><td>注册后进入待审核状态，需要 root 审核通过才能使用</td></tr><tr><td><strong>禁止注册（closed）</strong></td><td>关闭注册入口，新用户无法注册</td></tr></tbody></table><h3 id="注册步骤" tabindex="-1">注册步骤 <a class="header-anchor" href="#注册步骤" aria-label="Permalink to &quot;注册步骤&quot;">​</a></h3><ol><li>访问首页，点击「注册」按钮</li><li>填写用户名和密码，提交</li><li>根据注册模式不同： <ul><li><strong>开放模式</strong>：注册成功即激活，直接登录</li><li><strong>审批模式</strong>：注册成功后会提示「等待审核」，登录后角色为 guest，功能受限</li><li><strong>禁止模式</strong>：页面上看不到注册入口</li></ul></li></ol><h3 id="审核操作-仅-root" tabindex="-1">审核操作（仅 root） <a class="header-anchor" href="#审核操作-仅-root" aria-label="Permalink to &quot;审核操作（仅 root）&quot;">​</a></h3><ol><li>进入管理后台 → 「用户管理」Tab</li><li>找到状态为「待审核」的用户</li><li>点击「审核通过」按钮，该用户将升级为正式 user</li></ol><hr><h2 id="游客身份说明" tabindex="-1">游客身份说明 <a class="header-anchor" href="#游客身份说明" aria-label="Permalink to &quot;游客身份说明&quot;">​</a></h2><h3 id="自动分配" tabindex="-1">自动分配 <a class="header-anchor" href="#自动分配" aria-label="Permalink to &quot;自动分配&quot;">​</a></h3><p>当你没有登录时访问 ZViewer，系统会自动为你分配一个<strong>游客（guest）身份</strong>。你不需要注册就能使用。</p><h3 id="游客能做什么" tabindex="-1">游客能做什么 <a class="header-anchor" href="#游客能做什么" aria-label="Permalink to &quot;游客能做什么&quot;">​</a></h3><ul><li>加入已存在的房间，观看视频</li><li>发送评论和弹幕</li></ul><h3 id="游客不能做什么" tabindex="-1">游客不能做什么 <a class="header-anchor" href="#游客不能做什么" aria-label="Permalink to &quot;游客不能做什么&quot;">​</a></h3><ul><li>创建房间</li><li>进入管理后台</li><li>修改个人资料</li></ul><h3 id="转为正式用户" tabindex="-1">转为正式用户 <a class="header-anchor" href="#转为正式用户" aria-label="Permalink to &quot;转为正式用户&quot;">​</a></h3><p>如果你希望拥有更多功能，可以：</p><ol><li>点击页面上的「登录/注册」</li><li>注册一个新账号（如果注册模式为开放，即刻成为 user）</li><li>登录后自动获得更多权限</li></ol><hr><h2 id="房间创建权限" tabindex="-1">房间创建权限 <a class="header-anchor" href="#房间创建权限" aria-label="Permalink to &quot;房间创建权限&quot;">​</a></h2><p>管理员可以在「基础设置」中设置谁可以创建房间：</p><ul><li><strong>仅管理员（admin-only）</strong>：只有 root 和 admin 角色可以创建房间</li><li><strong>所有用户（all-users）</strong>：user 角色也可以创建房间</li></ul><p>游客在任何情况下都不能创建房间。</p><hr><h2 id="认证机制简述" tabindex="-1">认证机制简述 <a class="header-anchor" href="#认证机制简述" aria-label="Permalink to &quot;认证机制简述&quot;">​</a></h2><p>ZViewer 使用<strong>双令牌</strong>机制来保证安全：</p><ul><li><strong>Access Token（访问令牌）</strong>：短期有效（默认 15 分钟），用于验证每一次请求</li><li><strong>Refresh Token（刷新令牌）</strong>：长期有效（默认 7 天），用于在访问令牌过期后自动续期</li></ul><p>这些令牌通过 <strong>httpOnly Cookie</strong> 存储在浏览器中，普通 JavaScript 无法读取，有效防止 XSS 攻击窃取令牌。</p><p>简单来说：你登录一次，系统会记住你一段时间，期间不需要反复输入密码。</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="注册后不能创建房间" tabindex="-1">注册后不能创建房间 <a class="header-anchor" href="#注册后不能创建房间" aria-label="Permalink to &quot;注册后不能创建房间&quot;">​</a></h3><p>可能的原因：</p><ol><li>你的角色是 <strong>guest</strong>（待审核或刚注册）。需要 root 在后台审核通过后升级为 <strong>user</strong></li><li>房间创建权限设置为「仅管理员」，而你是 user 角色</li><li>注册模式为「开放注册」但系统未正确激活——请联系管理员检查</li></ol><h3 id="如何让用户成为管理员" tabindex="-1">如何让用户成为管理员？ <a class="header-anchor" href="#如何让用户成为管理员" aria-label="Permalink to &quot;如何让用户成为管理员？&quot;">​</a></h3><p>只有 <strong>root</strong> 可以提升其他用户为管理员：</p><ol><li>进入管理后台 → 「用户管理」Tab</li><li>找到该用户</li><li>点击「修改角色」，选择 admin</li><li>保存</li></ol><h3 id="忘记-root-密码怎么办" tabindex="-1">忘记 root 密码怎么办？ <a class="header-anchor" href="#忘记-root-密码怎么办" aria-label="Permalink to &quot;忘记 root 密码怎么办？&quot;">​</a></h3><p>如果丢失了 root 账户的密码，可以通过以下方式恢复：</p><ol><li>如果服务器上有命令行访问权限，可以执行重置脚本或直接修改数据库</li><li>如果在部署时设置了环境变量或初始配置，参考部署文档中的重置方式</li><li>联系服务器运维人员，通过数据库直接修改用户密码（需要了解数据库操作）</li></ol>',47)])])}const b=r(e,[["render",l]]);export{g as __pageData,b as default};
